  "Click the board to add a decision": { es: "Haz clic en la pizarra para añadir una decisión", ar: "انقر على اللوحة لإضافة قرار", zh: "点击画布添加判断", sw: "Bofya ubao kuongeza uamuzi", sv: "Klicka på tavlan för att lägga till ett beslut", de: "Klicke auf die Fläche, um eine Entscheidung hinzuzufügen", pt: "Clique no quadro para adicionar uma decisão", fr: "Cliquez sur le tableau pour ajouter une décision" },
  "Click the board to add a start or end shape": { es: "Haz clic en la pizarra para añadir un inicio o un fin", ar: "انقر على اللوحة لإضافة شكل بداية أو نهاية", zh: "点击画布添加开始或结束形状", sw: "Bofya ubao kuongeza umbo la mwanzo au mwisho", sv: "Klicka på tavlan för att lägga till en start- eller slutform", de: "Klicke auf die Fläche, um eine Start- oder Endform hinzuzufügen", pt: "Clique no quadro para adicionar uma forma de início ou fim", fr: "Cliquez sur le tableau pour ajouter une forme de début ou de fin" },
  "Click one shape, then another, to join them with an arrow": { es: "Haz clic en una forma y luego en otra para unirlas con una flecha", ar: "انقر على شكل ثم على آخر لربطهما بسهم", zh: "先点一个形状，再点另一个，用箭头连接它们", sw: "Bofya umbo moja, kisha jingine, kuziunganisha kwa mshale", sv: "Klicka på en form och sedan en annan för att koppla ihop dem med en pil", de: "Klicke auf eine Form und dann auf eine andere, um sie mit einem Pfeil zu verbinden", pt: "Clique numa forma e depois em outra para ligá-las com uma seta", fr: "Cliquez sur une forme puis sur une autre pour les relier par une flèche" },
  "Add an idea under the selected one (Tab)": { es: "Añade una idea debajo de la seleccionada (Tab)", ar: "أضف فكرة تحت الفكرة المحددة (Tab)", zh: "在选中的想法下添加想法（Tab）", sw: "Ongeza wazo chini ya lililochaguliwa (Tab)", sv: "Lägg till en idé under den markerade (Tab)", de: "Eine Idee unter der ausgewählten hinzufügen (Tab)", pt: "Adicionar uma ideia abaixo da selecionada (Tab)", fr: "Ajouter une idée sous celle sélectionnée (Tab)" },
  "Add an idea next to the selected one (Enter)": { es: "Añade una idea junto a la seleccionada (Intro)", ar: "أضف فكرة بجانب الفكرة المحددة (Enter)", zh: "在选中的想法旁添加想法（Enter）", sw: "Ongeza wazo kando ya lililochaguliwa (Enter)", sv: "Lägg till en idé bredvid den markerade (Enter)", de: "Eine Idee neben der ausgewählten hinzufügen (Enter)", pt: "Adicionar uma ideia ao lado da selecionada (Enter)", fr: "Ajouter une idée à côté de celle sélectionnée (Entrée)" },
  "Edit the text (double-click or F2)": { es: "Edita el texto (doble clic o F2)", ar: "عدّل النص (نقر مزدوج أو F2)", zh: "编辑文字（双击或 F2）", sw: "Hariri maandishi (bofya mara mbili au F2)", sv: "Ändra texten (dubbelklicka eller F2)", de: "Text bearbeiten (Doppelklick oder F2)", pt: "Editar o texto (duplo clique ou F2)", fr: "Modifier le texte (double-clic ou F2)" },
